import { lazy, Suspense, useMemo, useState, type ElementType, type ReactNode } from "react";
import { useDraftState } from "@/hooks/use-draft-state.ts";
import { useNavigate } from "react-router-dom";
import { format, formatDistanceToNow } from "date-fns";
import {
  Activity, AlertTriangle, ArrowRight, Banknote, Boxes, Building2, CheckCircle2, ClipboardCheck, ClipboardList,
  Clock3, PackageCheck, RefreshCw, Send, ShieldCheck, ShoppingCart, Truck, WalletCards, Warehouse,
} from "lucide-react";
import { endpoints } from "@/api/endpoints.ts";
import { useApiQuery, useApiQueryState, useApiMutation } from "@/hooks/use-api.ts";
import { useAuth } from "@/hooks/use-auth.ts";
import { emptyOperationsSnapshot, type GoodsFlowStage, type OperationalRole, type OperationsDashboardSnapshot } from "@/types/operations.ts";
import { Badge } from "@/components/ui/badge.tsx";
import { Button } from "@/components/ui/button.tsx";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card.tsx";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog.tsx";
import { Input } from "@/components/ui/input.tsx";
import { Label } from "@/components/ui/label.tsx";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select.tsx";
import { Textarea } from "@/components/ui/textarea.tsx";
import { toast } from "@/lib/system-message.ts";
import { cn } from "@/lib/utils.ts";
import { PageContentLoader } from "@/components/ui/page-loader.tsx";
import { queueOfflineOperation } from "@/lib/offline-store.ts";
const RoleAnalytics = lazy(() => import("./role-analytics.tsx"));

type DashboardRole = OperationalRole;
type MetricDefinition = { key: string; label: string; icon: ElementType; format?: "currency" | "percent"; tone?: "blue" | "green" | "amber" | "red" };
type ActionDefinition = { label: string; path?: string; icon: ElementType; action?: "issue" | "replenish" };

const roleConfig: Record<DashboardRole, { title: string; eyebrow: string; description: string; metrics: MetricDefinition[]; actions: ActionDefinition[] }> = {
  super_admin: {
    title: "Executive command center", eyebrow: "Super Admin", description: "A system-wide view of inventory health, procurement exposure, goods flow and operational exceptions.",
    metrics: [
      { key: "inventory_value", label: "Inventory value", icon: Boxes, format: "currency", tone: "blue" },
      { key: "monthly_spend", label: "Procurement spend MTD", icon: ShoppingCart, format: "currency", tone: "green" },
      { key: "open_purchase_orders", label: "Open purchase orders", icon: ClipboardList, tone: "amber" },
      { key: "workflow_exceptions", label: "System exceptions", icon: AlertTriangle, tone: "red" },
    ],
    actions: [{ label: "Procurement control", path: "/procurement", icon: ClipboardCheck }, { label: "Warehouse network", path: "/warehouses", icon: Warehouse }, { label: "Open reports", path: "/reports", icon: Activity }],
  },
  procurement_manager: {
    title: "Procurement control", eyebrow: "Procurement Manager", description: "Approve demand, protect committed spend and remove supplier or approval bottlenecks.",
    metrics: [
      { key: "pending_approvals", label: "Pending approvals", icon: ClipboardCheck, tone: "amber" },
      { key: "monthly_spend", label: "Spend this month", icon: ShoppingCart, format: "currency", tone: "blue" },
      { key: "supplier_delays", label: "Supplier delays", icon: Clock3, tone: "red" },
      { key: "budget_utilization", label: "Paid / committed", icon: ShieldCheck, format: "percent", tone: "green" },
    ],
    actions: [{ label: "Review approvals", path: "/procurement?status=draft", icon: ClipboardCheck }, { label: "Review suppliers", path: "/suppliers", icon: ShieldCheck }, { label: "Procurement report", path: "/reports?report=purchases", icon: Activity }],
  },
  procurement_officer: {
    title: "Procurement execution", eyebrow: "Procurement Officer", description: "Turn approved demand into supplier commitments and keep every order moving toward delivery.",
    metrics: [
      { key: "approved_requisitions", label: "Ready to source", icon: CheckCircle2, tone: "green" },
      { key: "purchase_orders_to_issue", label: "POs to issue", icon: Send, tone: "amber" },
      { key: "supplier_followups", label: "Supplier follow-ups", icon: Truck, tone: "blue" },
      { key: "overdue_deliveries", label: "Overdue deliveries", icon: AlertTriangle, tone: "red" },
    ],
    actions: [{ label: "Create purchase order", path: "/procurement", icon: ShoppingCart }, { label: "Contact suppliers", path: "/suppliers", icon: Send }, { label: "Track inbound", path: "/logistics", icon: Truck }],
  },
  store_keeper: {
    title: "Warehouse operations", eyebrow: "Store Keeper", description: "Receive, inspect, store and issue goods while keeping warehouse balances accurate and actionable.",
    metrics: [
      { key: "inventory_units", label: "Stock on hand", icon: Boxes, tone: "blue" },
      { key: "expected_receipts", label: "Expected receipts", icon: Truck, tone: "green" },
      { key: "open_transfers", label: "Transfers in motion", icon: RefreshCw, tone: "amber" },
      { key: "low_stock_items", label: "Low-stock items", icon: AlertTriangle, tone: "red" },
    ],
    actions: [{ label: "Warehouse stock", path: "/warehouses", icon: Warehouse }, { label: "Adjust or transfer", path: "/inventory", icon: Boxes }, { label: "Issue goods", icon: Send, action: "issue" }, { label: "Request replenishment", icon: ClipboardList, action: "replenish" }],
  },
  department_manager: {
    title: "Department operations", eyebrow: "Department Manager", description: "Track departmental orders, procurement progress and commitments for your assigned department.",
    metrics: [
      { key: "department_total_orders", label: "Department orders", icon: ClipboardList, tone: "blue" },
      { key: "department_pending_orders", label: "Pending requests", icon: Clock3, tone: "amber" },
      { key: "department_open_purchase_orders", label: "Open purchase orders", icon: ShoppingCart, tone: "green" },
      { key: "department_committed_spend", label: "Committed spend", icon: WalletCards, format: "currency", tone: "blue" },
    ],
    actions: [{ label: "Department workspace", path: "/department-workspace", icon: Building2 }],
  },
  accountant: {
    title: "Payment verification desk", eyebrow: "Accountant", description: "Review approved purchase orders, verify payments and keep proof-of-payment records complete.",
    metrics: [
      { key: "total_purchase_orders", label: "Purchase orders", icon: ClipboardList, tone: "blue" },
      { key: "pending_payment_verification", label: "Payments to verify", icon: WalletCards, tone: "amber" },
      { key: "verified_payments_mtd", label: "Verified this month", icon: CheckCircle2, format: "currency", tone: "green" },
      { key: "outstanding_payment_value", label: "Outstanding value", icon: Banknote, format: "currency", tone: "red" },
    ],
    actions: [{ label: "Review purchase orders", path: "/procurement", icon: ClipboardList }, { label: "Payment report", path: "/reports?report=purchase-payments", icon: Activity }],
  },
  supplier: {
    title: "Supplier command center", eyebrow: "Supplier", description: "Review purchase orders issued to your company, download documents and track delivery expectations.",
    metrics: [
      { key: "supplier_total_orders", label: "Total orders", icon: ClipboardList, tone: "blue" },
      { key: "supplier_open_orders", label: "Open orders", icon: PackageCheck, tone: "amber" },
      { key: "supplier_order_value", label: "Order value", icon: ShoppingCart, format: "currency", tone: "green" },
      { key: "supplier_overdue_orders", label: "Overdue orders", icon: AlertTriangle, tone: "red" },
    ],
    actions: [{ label: "Open supplier portal", path: "/supplier-portal", icon: ClipboardList }],
  },
};

const stageMeta: Record<GoodsFlowStage, { label: string; icon: ElementType }> = {
  requisition: { label: "Requested", icon: ClipboardList }, approval: { label: "Approved", icon: ClipboardCheck }, purchase_order: { label: "Ordered", icon: ShoppingCart }, supplier_dispatch: { label: "Dispatched", icon: Send }, goods_receipt: { label: "Received", icon: PackageCheck }, inspection: { label: "Inspected", icon: ShieldCheck }, stock_posting: { label: "In stock", icon: Warehouse },
};
const formatMoney = (value: number, currency: string) => `${currency} ${value.toLocaleString("en-TZ", { maximumFractionDigits: 0 })}`;
const toneClasses = { blue: "bg-primary/10 text-primary", green: "bg-emerald-500/10 text-emerald-600", amber: "bg-amber-500/10 text-amber-600", red: "bg-destructive/10 text-destructive" };

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const role = user?.role ?? "store_keeper";
  const fallbackRole: DashboardRole = user?.permissions.includes("supplier_orders.view") ? "supplier" : user?.permissions.includes("purchase_orders.payment_verify") ? "accountant" : user?.permissions.includes("purchase_orders.approve") ? "procurement_manager" : user?.permissions.includes("purchase_orders.create") ? "procurement_officer" : "store_keeper";
  const dashboardRole: DashboardRole = roleConfig[role as DashboardRole] ? role as DashboardRole : fallbackRole;
  const config = roleConfig[dashboardRole];
  const canUseStockDesk = dashboardRole !== "department_manager" && Boolean(user?.permissions.includes("inventory.view") && (user.permissions.includes("stock.issue") || user.permissions.includes("requisitions.create")));
  const visibleActions = config.actions.filter((action) => action.action === "issue" ? user?.permissions.includes("stock.issue") : action.action === "replenish" ? user?.permissions.includes("requisitions.create") : true);
  const [issueOpen, setIssueOpen] = useState(false);
  const [requestOpen, setRequestOpen] = useState(false);
  const [issueForm, setIssueForm] = useDraftState("dashboard-issue", { productId: "", warehouseId: "", quantity: "1", issuedTo: "", recipientContact: "", department: "", purpose: "", notes: "" });
  const [requestForm, setRequestForm] = useDraftState("dashboard-request", { productId: "", warehouseId: "", quantity: "1", reason: "Low or ending stock", notes: "" });
  const snapshotQuery = useApiQueryState(endpoints.dashboard.getOperations, { role }, { refreshInterval: 15_000 });
  const snapshot = (snapshotQuery.data ?? emptyOperationsSnapshot) as OperationsDashboardSnapshot;
  const currency = user?.organization?.currency ?? "TSHS";
  // Product, warehouse and issue data are secondary to the dashboard shell.
  // Only fetch the form options when a stock action is actually opened, and
  // fetch the recent issue list after the primary snapshot has rendered.
  const stockActionOpen = issueOpen || requestOpen;
  const products = useApiQuery(endpoints.inventory.listProducts, canUseStockDesk && stockActionOpen ? { includeInactive: false } : "skip");
  const warehouses = useApiQuery(endpoints.warehouses.listWarehouses, canUseStockDesk && stockActionOpen ? {} : "skip");
  const issues = useApiQuery(endpoints.inventory.listIssues, canUseStockDesk && !snapshotQuery.isLoading ? {} : "skip");
  const issueGoods = useApiMutation(endpoints.inventory.issueGoods);
  const createReplenishmentRequest = useApiMutation(endpoints.inventory.createReplenishmentRequest);
  const issueStock = useApiQuery(endpoints.warehouses.getWarehouseStock, issueOpen && issueForm.warehouseId ? { warehouseId: issueForm.warehouseId } : "skip");
  const metricValues = useMemo(() => new Map((snapshot?.metrics ?? []).map((metric) => [metric.key, metric])), [snapshot?.metrics]);
  const issueStockByProduct = useMemo(() => new Map((issueStock ?? []).map((row: any) => [String(row.product?.id ?? row.productId), Number(row.available ?? row.quantity ?? 0)])), [issueStock]);
  const issueAvailable = issueStockByProduct.get(issueForm.productId) ?? 0;
  const issueStockLoading = Boolean(issueForm.warehouseId) && issueStock === undefined;
  const loading = snapshotQuery.isLoading;

  const saveIssue = async () => {
    if (!issueForm.productId || !issueForm.warehouseId || !issueForm.issuedTo.trim() || !issueForm.quantity) return toast.error("Select a product and warehouse, then enter who will receive the goods");
    if (!issueStockLoading && Number(issueForm.quantity) > issueAvailable) return toast.error(`Only ${issueAvailable} available in the selected warehouse`);
    try { if (!navigator.onLine) { await queueOfflineOperation("issue_stock", { productId: Number(issueForm.productId), warehouseId: Number(issueForm.warehouseId), quantity: Number(issueForm.quantity), issuedTo: issueForm.issuedTo.trim(), recipientContact: issueForm.recipientContact.trim() || undefined, department: issueForm.department.trim() || undefined, purpose: issueForm.purpose.trim() || undefined, notes: issueForm.notes.trim() || undefined, baseQuantity: issueAvailable }); toast.success("No connection. Issue queued securely for synchronization"); setIssueOpen(false); return; } await issueGoods({ productId: Number(issueForm.productId), warehouseId: Number(issueForm.warehouseId), quantity: Number(issueForm.quantity), issuedTo: issueForm.issuedTo.trim(), recipientContact: issueForm.recipientContact.trim() || undefined, department: issueForm.department.trim() || undefined, purpose: issueForm.purpose.trim() || undefined, notes: issueForm.notes.trim() || undefined }); toast.success("Goods issued and recorded"); setIssueOpen(false); setIssueForm({ productId: "", warehouseId: "", quantity: "1", issuedTo: "", recipientContact: "", department: "", purpose: "", notes: "" }); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to issue goods"); }
  };
  const saveReplenishmentRequest = async () => {
    if (!requestForm.productId || !requestForm.warehouseId || !requestForm.quantity) return toast.error("Select a product and warehouse, then enter the requested quantity");
    try { await createReplenishmentRequest({ productId: Number(requestForm.productId), warehouseId: Number(requestForm.warehouseId), quantity: Number(requestForm.quantity), reason: requestForm.reason.trim() || undefined, notes: requestForm.notes.trim() || undefined }); toast.success("Replenishment request sent to procurement"); setRequestOpen(false); setRequestForm({ productId: "", warehouseId: "", quantity: "1", reason: "Low or ending stock", notes: "" }); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to send replenishment request"); }
  };

  return <div className="space-y-4 p-4 pb-24 md:p-6 md:pb-6">
    <div className="flex flex-col gap-3 rounded-xl border bg-card px-4 py-3 shadow-sm lg:flex-row lg:items-center lg:justify-between">
      <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge variant="outline" className="border-primary/25 bg-primary/5 text-primary">{config.eyebrow}</Badge><span className="flex items-center gap-1.5 text-xs text-emerald-600"><span className="size-1.5 rounded-full bg-emerald-500" />Live data · 15s refresh</span></div><h2 className="mt-1 text-xl font-semibold tracking-tight">{config.title}</h2><p className="truncate text-sm text-muted-foreground">{config.description}</p><p className="mt-1 text-[11px] text-muted-foreground">{format(new Date(), "EEEE, MMMM d, yyyy")} · {dashboardRole === "department_manager" ? "Authorized department scope" : "Authorized warehouse and organization scope"}</p></div>
      <div className="flex flex-wrap gap-2">{visibleActions.map((action) => <Button key={action.label} variant={action.action ? "default" : "outline"} size="sm" onClick={() => action.action === "issue" ? setIssueOpen(true) : action.action === "replenish" ? setRequestOpen(true) : navigate(action.path ?? "/")}><action.icon className="size-4" />{action.label}</Button>)}</div>
    </div>

    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{config.metrics.map((metric) => { const entry = metricValues.get(metric.key); const value = entry?.value ?? 0; return <Card key={metric.key} className="shadow-sm"><CardContent className="flex items-center justify-between p-4"><div className="min-w-0"><p className="truncate text-[11px] font-medium uppercase tracking-wide text-muted-foreground">{metric.label}</p><p className="mt-1 text-xl font-semibold tracking-tight">{loading ? "—" : metric.format === "currency" ? formatMoney(value, currency) : metric.format === "percent" ? `${value}%` : value.toLocaleString()}</p><p className="mt-1 text-[11px] text-muted-foreground">{dashboardRole === "department_manager" ? "Live department total" : "Live organization total"}</p></div><div className={cn("rounded-lg p-2.5", toneClasses[metric.tone ?? "blue"])}><metric.icon className="size-5" /></div></CardContent></Card>; })}</div>

    {dashboardRole === "department_manager" ? <DepartmentDashboardContent snapshot={snapshot} currency={currency} navigate={navigate} /> : dashboardRole === "supplier" ? <SupplierDashboardContent snapshot={snapshot} currency={currency} navigate={navigate} /> : <>
      <Attention snapshot={snapshot} role={dashboardRole} currency={currency} navigate={navigate} />
      <GoodsFlow snapshot={snapshot} role={dashboardRole} navigate={navigate} />
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1.5fr)_minmax(280px,1fr)]"><WorkQueue snapshot={snapshot} role={dashboardRole} currency={currency} navigate={navigate} /><Exceptions snapshot={snapshot} navigate={navigate} /></div>
      <Suspense fallback={<div className="grid gap-4 xl:grid-cols-2"><PageContentLoader variant="cards" /><PageContentLoader variant="cards" /></div>}><RoleAnalytics snapshot={snapshot} role={dashboardRole} currency={currency} /></Suspense>
      {canUseStockDesk && <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="text-sm">Recent goods issued</CardTitle><CardDescription>Recorded issues from the stock movement ledger.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{(issues as Array<Record<string, any>> | undefined)?.length ? <div className="divide-y">{(issues as Array<Record<string, any>>).slice(0, 6).map((issue) => <div key={String(issue.id)} className="flex flex-wrap items-center gap-3 py-2.5"><Badge variant="outline" className="text-[10px]">{String(issue.reference)}</Badge><div className="min-w-40 flex-1"><p className="text-sm font-medium">{String((issue.product as Record<string, unknown>)?.name ?? "Product")}</p><p className="text-xs text-muted-foreground">To {String(issue.issuedTo)}{issue.department ? ` · ${String(issue.department)}` : ""} · {String((issue.warehouse as Record<string, unknown>)?.name ?? "Warehouse")}</p></div><span className="text-sm font-semibold">{String(issue.quantity)} issued</span></div>)}</div> : <EmptyPanel icon={Send} title="No goods issued yet" description="Use Issue goods to record stock handed to a person or department." />}</CardContent></Card>}
      <ActivityPanel snapshot={snapshot} role={dashboardRole} />
    </>}

    <Dialog open={issueOpen} onOpenChange={setIssueOpen}><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Issue goods to a person</DialogTitle></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Product *</Label><Select value={issueForm.productId} onValueChange={(value) => setIssueForm({ ...issueForm, productId: value })}><SelectTrigger><SelectValue placeholder="Select product" /></SelectTrigger><SelectContent>{(products as Array<Record<string, any>> | undefined)?.map((product) => { const productStock = issueStockByProduct.get(String(product._id)) ?? 0; return <SelectItem key={String(product._id)} value={String(product._id)}>{String(product.name)}{product.sku ? ` · ${String(product.sku)}` : ""} · {issueStockLoading ? "loading stock…" : `available ${productStock}`}</SelectItem>; })}</SelectContent></Select></div><div className="space-y-2"><Label>Warehouse *</Label><Select value={issueForm.warehouseId} onValueChange={(value) => setIssueForm({ ...issueForm, warehouseId: value, productId: "" })}><SelectTrigger><SelectValue placeholder="Select warehouse" /></SelectTrigger><SelectContent>{(warehouses as Array<Record<string, any>> | undefined)?.map((warehouse) => <SelectItem key={String(warehouse._id)} value={String(warehouse._id)}>{String(warehouse.name)}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Quantity *</Label><Input type="number" min="0.001" step="0.001" value={issueForm.quantity} onChange={(event) => setIssueForm({ ...issueForm, quantity: event.target.value })} /><p className={cn("text-xs", !issueStockLoading && issueForm.productId && Number(issueForm.quantity) > issueAvailable ? "text-destructive" : "text-muted-foreground")}>{issueStockLoading ? "Checking warehouse stock…" : issueForm.productId ? `${issueAvailable} available in selected warehouse` : "Select a product to see availability"}</p></div><div className="space-y-2"><Label>Issued to *</Label><Input value={issueForm.issuedTo} onChange={(event) => setIssueForm({ ...issueForm, issuedTo: event.target.value })} placeholder="Person's full name" /></div><div className="space-y-2"><Label>Contact</Label><Input value={issueForm.recipientContact} onChange={(event) => setIssueForm({ ...issueForm, recipientContact: event.target.value })} placeholder="Phone or email" /></div><div className="space-y-2"><Label>Department</Label><Input value={issueForm.department} onChange={(event) => setIssueForm({ ...issueForm, department: event.target.value })} /></div><div className="space-y-2 sm:col-span-2"><Label>Purpose</Label><Input value={issueForm.purpose} onChange={(event) => setIssueForm({ ...issueForm, purpose: event.target.value })} placeholder="Why are the goods being issued?" /></div><div className="space-y-2 sm:col-span-2"><Label>Notes</Label><Textarea value={issueForm.notes} onChange={(event) => setIssueForm({ ...issueForm, notes: event.target.value })} placeholder="Additional issue notes" /></div></div><DialogFooter><Button variant="outline" onClick={() => setIssueOpen(false)}>Cancel</Button><Button onClick={() => void saveIssue()}>Issue and record</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={requestOpen} onOpenChange={setRequestOpen}><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Request stock replenishment</DialogTitle></DialogHeader><p className="text-sm text-muted-foreground">This request will be sent to procurement for sourcing. Store keepers do not create purchase orders.</p><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Product *</Label><Select value={requestForm.productId} onValueChange={(value) => setRequestForm({ ...requestForm, productId: value })}><SelectTrigger><SelectValue placeholder="Select product" /></SelectTrigger><SelectContent>{(products as Array<Record<string, any>> | undefined)?.map((product) => <SelectItem key={String(product._id)} value={String(product._id)}>{String(product.name)} · stock {String(product.totalStock ?? 0)}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Warehouse *</Label><Select value={requestForm.warehouseId} onValueChange={(value) => setRequestForm({ ...requestForm, warehouseId: value })}><SelectTrigger><SelectValue placeholder="Select warehouse" /></SelectTrigger><SelectContent>{(warehouses as Array<Record<string, any>> | undefined)?.map((warehouse) => <SelectItem key={String(warehouse._id)} value={String(warehouse._id)}>{String(warehouse.name)}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Quantity needed *</Label><Input type="number" min="0.001" step="0.001" value={requestForm.quantity} onChange={(event) => setRequestForm({ ...requestForm, quantity: event.target.value })} /></div><div className="space-y-2 sm:col-span-2"><Label>Reason</Label><Input value={requestForm.reason} onChange={(event) => setRequestForm({ ...requestForm, reason: event.target.value })} /></div><div className="space-y-2 sm:col-span-2"><Label>Notes</Label><Textarea value={requestForm.notes} onChange={(event) => setRequestForm({ ...requestForm, notes: event.target.value })} placeholder="Optional details for procurement" /></div></div><DialogFooter><Button variant="outline" onClick={() => setRequestOpen(false)}>Cancel</Button><Button onClick={() => void saveReplenishmentRequest()}>Send to procurement</Button></DialogFooter></DialogContent></Dialog>
  </div>;
}

function Attention({ snapshot, role, currency, navigate }: { snapshot?: OperationsDashboardSnapshot; role: DashboardRole; currency: string; navigate: (path: string) => void }) {
  const summary = snapshot?.summary;
  const items = role === "accountant" ? [{ label: "Awaiting manager approval", value: summary?.pendingManagerApprovalCount ?? 0, path: "/procurement?status=draft", tone: "amber" }, { label: "Payments to verify", value: summary?.pendingPaymentVerificationCount ?? findMetric(snapshot, "pending_payment_verification"), path: "/procurement?status=sent", tone: "blue" }, { label: "Verified this month", value: summary?.verifiedPaymentsMtd ?? findMetric(snapshot, "verified_payments_mtd"), path: "/procurement", tone: "green", money: true }, { label: "Outstanding value", value: summary?.outstandingPaymentValue ?? findMetric(snapshot, "outstanding_payment_value"), path: "/procurement", tone: "red", money: true }] : role === "store_keeper" ? [{ label: "Out of stock", value: summary?.outOfStockItems ?? 0, path: "/inventory", tone: "red" }, { label: "Low stock", value: summary?.lowStockItems ?? 0, path: "/inventory", tone: "amber" }, { label: "Receipts today", value: summary?.receiptsToday ?? 0, path: "/procurement", tone: "green" }, { label: "Issues today", value: summary?.issuesToday ?? 0, path: "/inventory", tone: "blue" }] : role === "procurement_officer" ? [{ label: "Approved to source", value: findMetric(snapshot, "approved_requisitions"), path: "/procurement", tone: "green" }, { label: "POs to issue", value: findMetric(snapshot, "purchase_orders_to_issue"), path: "/procurement?status=sent", tone: "amber" }, { label: "Follow-ups", value: findMetric(snapshot, "supplier_followups"), path: "/suppliers", tone: "blue" }, { label: "Overdue", value: findMetric(snapshot, "overdue_deliveries"), path: "/logistics", tone: "red" }] : [{ label: "Pending approvals", value: summary?.pendingApprovalCount ?? findMetric(snapshot, "pending_approvals"), path: "/procurement?status=draft", tone: "amber" }, { label: "Open PO value", value: summary?.openPurchaseOrderValue ?? 0, path: "/procurement", tone: "blue", money: true }, { label: "Delayed deliveries", value: findMetric(snapshot, "supplier_delays"), path: "/logistics", tone: "red" }, { label: "Out of stock", value: summary?.outOfStockItems ?? 0, path: "/inventory", tone: "amber" }];
  return <Card className="shadow-sm"><CardHeader className="px-4 py-3"><div className="flex items-center justify-between"><div><CardTitle className="flex items-center gap-2 text-sm"><AlertTriangle className="size-4 text-amber-500" />Attention now</CardTitle><CardDescription>Click an item to open its operational workspace.</CardDescription></div><Badge variant="outline" className="text-[10px]">Live</Badge></div></CardHeader><CardContent className="grid gap-2 px-4 pb-4 sm:grid-cols-2 xl:grid-cols-4">{items.map((item) => <button key={item.label} type="button" onClick={() => navigate(item.path)} className="flex items-center justify-between rounded-lg border bg-background px-3 py-2.5 text-left transition-colors hover:border-primary/40 hover:bg-primary/[0.03]"><span><span className="block text-xs text-muted-foreground">{item.label}</span><span className="mt-0.5 block text-base font-semibold">{item.money ? formatMoney(item.value, currency) : item.value.toLocaleString()}</span></span><span className={cn("rounded-md p-1.5", toneClasses[item.tone as keyof typeof toneClasses])}><ArrowRight className="size-3.5" /></span></button>)}</CardContent></Card>;
}

function DepartmentDashboardContent({ snapshot, currency, navigate }: { snapshot: OperationsDashboardSnapshot; currency: string; navigate: (path: string) => void }) {
  const summary = snapshot.summary;
  const attention = [
    { label: "Pending requests", value: summary.departmentPendingOrders ?? 0, tone: "amber" },
    { label: "Approved requests", value: summary.departmentApprovedOrders ?? 0, tone: "blue" },
    { label: "Overdue deliveries", value: summary.departmentOverdueCount ?? 0, tone: "red" },
    { label: "Committed spend", value: summary.departmentCommittedSpend ?? 0, tone: "green", money: true },
  ];
  const flow = [
    { label: "Requested", stage: "requisition" as GoodsFlowStage },
    { label: "Approved", stage: "approval" as GoodsFlowStage },
    { label: "Ordered", stage: "purchase_order" as GoodsFlowStage },
    { label: "Supplier / dispatch", stage: "supplier_dispatch" as GoodsFlowStage },
    { label: "Fulfilled", stage: "goods_receipt" as GoodsFlowStage },
  ];
  const countFor = (stage: GoodsFlowStage) => snapshot.flow.find((entry) => entry.stage === stage)?.count ?? 0;
  const delayedFor = (stage: GoodsFlowStage) => snapshot.flow.find((entry) => entry.stage === stage)?.delayed ?? 0;
  const queue = snapshot.workQueue.slice(0, 8);
  const exceptions = snapshot.exceptions.slice(0, 6);

  return <>
    <Card className="border-primary/15 bg-primary/[0.02] shadow-sm"><CardHeader className="px-4 py-3"><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle className="flex items-center gap-2 text-sm"><Building2 className="size-4 text-primary" />Department attention</CardTitle><CardDescription>{snapshot.department ? `${snapshot.department.name} · ${snapshot.department.code}` : "Assign this account to an active department to see departmental records."}</CardDescription></div><Badge variant="outline" className="text-[10px]">Department scope</Badge></div></CardHeader><CardContent className="grid gap-2 px-4 pb-4 sm:grid-cols-2 xl:grid-cols-4">{attention.map((item) => <button key={item.label} type="button" onClick={() => navigate("/department-workspace")} className="flex items-center justify-between rounded-lg border bg-background px-3 py-2.5 text-left transition-colors hover:border-primary/40 hover:bg-primary/[0.03]"><span><span className="block text-xs text-muted-foreground">{item.label}</span><span className="mt-0.5 block text-base font-semibold">{item.money ? formatMoney(item.value, currency) : item.value.toLocaleString()}</span></span><span className={cn("rounded-md p-1.5", toneClasses[item.tone as keyof typeof toneClasses])}><ArrowRight className="size-3.5" /></span></button>)}</CardContent></Card>

    <Card className="overflow-hidden border-border/80 shadow-sm"><CardHeader className="border-b bg-gradient-to-r from-primary/[0.045] via-card to-card px-5 py-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle className="text-sm font-semibold">Department request flow</CardTitle><CardDescription>Request → approval → order → supplier → fulfilment</CardDescription></div><Badge variant="outline" className="gap-1 border-emerald-500/25 bg-emerald-500/[0.06] px-1.5 py-0.5 text-[10px] font-medium text-emerald-700 dark:text-emerald-400"><span className="size-1.5 rounded-full bg-emerald-500" />Live</Badge></div></CardHeader><CardContent className="bg-muted/[0.16] p-4"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{flow.map((entry, index) => { const count = countFor(entry.stage); const delayed = delayedFor(entry.stage); const Icon = stageMeta[entry.stage].icon; return <button type="button" key={entry.stage} onClick={() => navigate("/department-workspace")} className={cn("relative min-h-24 rounded-xl border bg-card p-3 text-left transition-colors hover:border-primary/45", delayed > 0 && "border-destructive/45 bg-destructive/[0.035]")}><div className="flex items-start justify-between gap-2"><span className={cn("flex size-8 items-center justify-center rounded-lg", count > 0 ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground")}><Icon className="size-4" /></span><span className="rounded-full border bg-background/70 px-2 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground">{String(index + 1).padStart(2, "0")}</span></div><p className="mt-3 truncate text-xs font-medium">{entry.label}</p><p className="mt-0.5 text-xl font-semibold tabular-nums">{count.toLocaleString()}</p>{delayed > 0 && <Badge variant="destructive" className="mt-1 text-[10px]">{delayed} delayed</Badge>}</button>; })}</div></CardContent></Card>

    <div className="grid gap-4 xl:grid-cols-[minmax(0,1.5fr)_minmax(280px,1fr)]"><Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="text-sm">Department work queue</CardTitle><CardDescription>Requests and purchase orders assigned to your department.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{queue.length ? <div className="divide-y">{queue.map((item) => <button type="button" key={item.id} onClick={() => navigate("/department-workspace")} className="flex w-full items-center gap-3 py-3 text-left hover:bg-muted/20"><div className={cn("mt-0.5 size-2 shrink-0 rounded-full", item.priority === "high" || item.priority === "critical" ? "bg-destructive" : "bg-primary")} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-medium">{item.title}</p><Badge variant="outline" className="text-[10px] capitalize">{item.status}</Badge></div><p className="mt-0.5 truncate text-xs text-muted-foreground">{item.reference}{item.supplier ? ` · ${item.supplier}` : ""}{item.location ? ` · ${item.location}` : ""}</p></div>{item.amount !== undefined && <span className="shrink-0 text-xs font-semibold">{formatMoney(item.amount, currency)}</span>}<ArrowRight className="size-4 shrink-0 text-muted-foreground" /></button>)}</div> : <EmptyPanel icon={ClipboardList} title="No department work pending" description="New departmental requests and allocated purchase orders will appear here." />}</CardContent></Card><Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="flex items-center gap-2 text-sm"><AlertTriangle className="size-4 text-amber-500" />Department exceptions</CardTitle><CardDescription>Overdue or aging records that need follow-up.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{exceptions.length ? <div className="space-y-2">{exceptions.map((item) => <button type="button" key={item.id} onClick={() => navigate("/department-workspace")} className="w-full rounded-lg border border-amber-500/25 bg-amber-500/[0.04] p-3 text-left hover:bg-amber-500/[0.08]"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-medium">{item.reference}</p><Badge variant="destructive" className="text-[10px]">{item.priority}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{item.title}{item.supplier ? ` · ${item.supplier}` : ""}</p></button>)}</div> : <EmptyPanel icon={CheckCircle2} title="No department exceptions" description="Aging requests and overdue departmental deliveries will be highlighted here." />}</CardContent></Card></div>

    <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="flex items-center gap-2 text-sm"><Activity className="size-4" />Department activity</CardTitle><CardDescription>Recent requests and procurement updates for this department.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{snapshot.activity.length ? <div className="grid gap-3 md:grid-cols-2">{snapshot.activity.slice(0, 8).map((event) => <div key={event.id} className="flex gap-3"><div className="mt-1.5 size-2 shrink-0 rounded-full bg-primary" /><div className="min-w-0"><p className="truncate text-sm"><span className="font-medium">{event.actor}</span> {event.action} <span className="font-medium">{event.reference}</span></p><p className="text-xs text-muted-foreground">{formatDistanceToNow(new Date(event.occurredAt), { addSuffix: true })} · {stageMeta[event.stage]?.label ?? "Department workflow"}</p></div></div>)}</div> : <EmptyPanel icon={Activity} title="No department activity yet" description="Department requests and purchasing updates will appear here as work begins." />}</CardContent></Card>
  </>;
}

function SupplierDashboardContent({ snapshot, currency, navigate }: { snapshot: OperationsDashboardSnapshot; currency: string; navigate: (path: string) => void }) {
  return <><Card className="border-primary/15 bg-primary/[0.02] shadow-sm"><CardHeader className="px-4 py-3"><div className="flex items-center justify-between gap-3"><div><CardTitle className="flex items-center gap-2 text-sm"><ClipboardList className="size-4 text-primary" />Supplier attention</CardTitle><CardDescription>Only orders linked to your supplier company are shown here.</CardDescription></div><Badge variant="outline">Company scope</Badge></div></CardHeader><CardContent className="grid gap-3 px-4 pb-4 sm:grid-cols-2"><button type="button" onClick={() => navigate("/supplier-portal")} className="rounded-xl border bg-background p-4 text-left hover:border-primary/40"><p className="text-xs text-muted-foreground">Open orders</p><p className="mt-1 text-2xl font-semibold">{snapshot.summary.openPurchaseOrderValue ? formatMoney(snapshot.summary.openPurchaseOrderValue, currency) : "No open value"}</p><p className="mt-1 text-xs text-muted-foreground">Review current order commitments</p></button><button type="button" onClick={() => navigate("/supplier-portal")} className="rounded-xl border bg-background p-4 text-left hover:border-primary/40"><p className="text-xs text-muted-foreground">Exceptions</p><p className="mt-1 text-2xl font-semibold">{snapshot.exceptions.length}</p><p className="mt-1 text-xs text-muted-foreground">Delivery dates needing attention</p></button></CardContent></Card><Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="text-sm">Supplier work queue</CardTitle><CardDescription>Orders awaiting confirmation or delivery follow-up.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{snapshot.workQueue.length ? <div className="divide-y">{snapshot.workQueue.slice(0, 8).map((item) => <button type="button" key={item.id} onClick={() => navigate("/supplier-portal")} className="flex w-full items-center gap-3 py-3 text-left hover:bg-muted/20"><span className={cn("size-2 rounded-full", item.priority === "high" ? "bg-destructive" : "bg-primary")} /><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium">{item.reference} · {item.title}</span><span className="block truncate text-xs capitalize text-muted-foreground">{item.status}{item.dueAt ? ` · due ${format(new Date(item.dueAt), "dd MMM")}` : ""}</span></span><span className="text-xs font-semibold">{formatMoney(item.amount ?? 0, currency)}</span><ArrowRight className="size-4 text-muted-foreground" /></button>)}</div> : <EmptyPanel icon={CheckCircle2} title="No supplier actions pending" description="New approved orders will appear in your supplier portal." />}</CardContent></Card></>;
}

function GoodsFlow({ snapshot, role, navigate }: { snapshot?: OperationsDashboardSnapshot; role: DashboardRole; navigate: (path: string) => void }) {
  const summary = snapshot?.summary;
  const flow = snapshot?.flow ?? [];
  const byStage = (stage: GoodsFlowStage) => flow.find((item) => item.stage === stage)?.count ?? 0;
  const delayed = (stage: GoodsFlowStage) => flow.find((item) => item.stage === stage)?.delayed ?? 0;
  const items = role === "accountant" ? [{ label: "Manager approval", value: byStage("approval"), stage: "approval" as GoodsFlowStage, path: "/procurement?status=draft" }, { label: "Approved orders", value: byStage("purchase_order"), stage: "purchase_order" as GoodsFlowStage, path: "/procurement" }, { label: "Payment verification", value: summary?.pendingPaymentVerificationCount ?? 0, stage: "supplier_dispatch" as GoodsFlowStage, path: "/procurement" }, { label: "Paid orders", value: byStage("stock_posting"), stage: "stock_posting" as GoodsFlowStage, path: "/procurement" }] : role === "store_keeper" ? [{ label: "Incoming", value: byStage("supplier_dispatch"), stage: "supplier_dispatch" as GoodsFlowStage, path: "/procurement" }, { label: "Received", value: byStage("goods_receipt"), stage: "goods_receipt" as GoodsFlowStage, path: "/procurement" }, { label: "Inspected", value: byStage("inspection"), stage: "inspection" as GoodsFlowStage, path: "/inventory" }, { label: "Stored", value: byStage("stock_posting"), stage: "stock_posting" as GoodsFlowStage, path: "/warehouses" }, { label: "Issued / transferred", value: (summary?.issuesToday ?? 0) + (summary?.transfersToday ?? 0), stage: "stock_posting" as GoodsFlowStage, path: "/inventory" }] : role === "procurement_manager" ? [{ label: "Requested", value: byStage("requisition"), stage: "requisition" as GoodsFlowStage, path: "/procurement" }, { label: "Approved", value: byStage("approval"), stage: "approval" as GoodsFlowStage, path: "/procurement" }, { label: "RFQ / ordered", value: byStage("purchase_order"), stage: "purchase_order" as GoodsFlowStage, path: "/procurement" }, { label: "Supplier / dispatch", value: byStage("supplier_dispatch"), stage: "supplier_dispatch" as GoodsFlowStage, path: "/logistics" }] : role === "procurement_officer" ? [{ label: "Approved demand", value: byStage("approval"), stage: "approval" as GoodsFlowStage, path: "/procurement" }, { label: "Orders to issue", value: byStage("purchase_order"), stage: "purchase_order" as GoodsFlowStage, path: "/procurement?status=draft" }, { label: "Supplier response", value: byStage("supplier_dispatch"), stage: "supplier_dispatch" as GoodsFlowStage, path: "/suppliers" }, { label: "Expected delivery", value: byStage("goods_receipt"), stage: "goods_receipt" as GoodsFlowStage, path: "/logistics" }] : [{ label: "Requested", value: byStage("requisition"), stage: "requisition" as GoodsFlowStage, path: "/procurement" }, { label: "Approved", value: byStage("approval"), stage: "approval" as GoodsFlowStage, path: "/procurement" }, { label: "Ordered", value: byStage("purchase_order"), stage: "purchase_order" as GoodsFlowStage, path: "/procurement" }, { label: "Dispatched", value: byStage("supplier_dispatch"), stage: "supplier_dispatch" as GoodsFlowStage, path: "/logistics" }, { label: "Received", value: byStage("goods_receipt"), stage: "goods_receipt" as GoodsFlowStage, path: "/procurement" }, { label: "Inspected", value: byStage("inspection"), stage: "inspection" as GoodsFlowStage, path: "/inventory" }, { label: "In stock", value: byStage("stock_posting"), stage: "stock_posting" as GoodsFlowStage, path: "/warehouses" }];
  const columns = items.length >= 7 ? "xl:grid-cols-7" : items.length === 5 ? "xl:grid-cols-5" : "xl:grid-cols-4";
  const activeStages = items.filter((item) => item.value > 0).length;
  const delayedStages = items.filter((item) => delayed(item.stage) > 0).length;
  const subtitle = role === "accountant" ? "Manager approval → approved order → payment verification → paid" : role === "store_keeper" ? "Incoming → received → inspected → stored → issued / transferred" : role === "procurement_officer" ? "Actionable procurement stages for today’s execution" : "Demand to stock, with exceptions visible at each hand-off";
  return <Card className="overflow-hidden border-border/80 shadow-sm"><CardHeader className="border-b bg-gradient-to-r from-primary/[0.045] via-card to-card px-5 py-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="mb-1 flex items-center gap-2"><CardTitle className="text-sm font-semibold">Goods flow control</CardTitle><Badge variant="outline" className="gap-1 border-emerald-500/25 bg-emerald-500/[0.06] px-1.5 py-0.5 text-[10px] font-medium text-emerald-700 dark:text-emerald-400"><span className="size-1.5 rounded-full bg-emerald-500" />Live</Badge></div><CardDescription>{subtitle}</CardDescription></div><div className="flex items-center gap-2 text-[11px] text-muted-foreground"><span>{activeStages} of {items.length} stages active</span>{delayedStages > 0 && <Badge variant="destructive" className="text-[10px]">{delayedStages} delayed</Badge>}<RefreshCw className="size-3.5" /></div></div></CardHeader><CardContent className="bg-muted/[0.16] p-4"><div className={cn("grid gap-3", "grid-cols-1 sm:grid-cols-2 lg:grid-cols-4", columns)}>{items.map((item, index) => { const Icon = stageMeta[item.stage].icon; const delay = delayed(item.stage); const active = item.value > 0; return <div key={`${item.label}-${index}`} className="relative"><button type="button" aria-label={`Open ${item.label} records`} onClick={() => navigate(item.path)} className={cn("group flex min-h-[122px] w-full flex-col rounded-xl border p-3.5 text-left transition-all", active ? "border-primary/25 bg-card shadow-sm hover:-translate-y-0.5 hover:border-primary/55 hover:shadow-md" : "border-border/80 bg-card/60 hover:border-primary/35 hover:bg-card", delay > 0 && "border-destructive/45 bg-destructive/[0.035]")}><div className="flex items-start justify-between gap-2"><span className={cn("flex size-8 items-center justify-center rounded-lg", active ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground", delay > 0 && "bg-destructive/10 text-destructive")}><Icon className="size-4" /></span><span className="rounded-full border bg-background/70 px-2 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground">{String(index + 1).padStart(2, "0")}</span></div><div className="mt-auto pt-4"><p className={cn("truncate text-xs font-medium", active ? "text-foreground" : "text-muted-foreground")}>{item.label}</p><div className="mt-0.5 flex items-baseline gap-1.5"><span className={cn("text-2xl font-semibold tracking-tight", !active && "text-muted-foreground")}>{item.value.toLocaleString()}</span><span className="text-[10px] text-muted-foreground">records</span></div></div>{delay > 0 && <Badge variant="destructive" className="mt-2 w-fit text-[10px]">{delay} delayed</Badge>}</button>{index < items.length - 1 && <span aria-hidden="true" className="pointer-events-none absolute -right-3 top-1/2 z-10 hidden w-6 -translate-y-1/2 items-center xl:flex"><span className="h-px flex-1 bg-border" /><ArrowRight className="size-3.5 shrink-0 text-muted-foreground" /></span>}</div>; })}</div>{activeStages === 0 && <div className="mt-3 rounded-lg border border-dashed border-primary/20 bg-card/70 px-3 py-2 text-center text-xs text-muted-foreground">No records are currently moving through this workflow. New activity will appear here automatically.</div>}</CardContent></Card>;
}

function WorkQueue({ snapshot, role, currency, navigate }: { snapshot?: OperationsDashboardSnapshot; role: DashboardRole; currency: string; navigate: (path: string) => void }) {
  const title = role === "accountant" ? "Payment verification queue" : role === "store_keeper" ? "Warehouse work queue" : role === "procurement_officer" ? "My work queue" : role === "procurement_manager" ? "Approval and supplier queue" : "System control queue";
  const description = role === "accountant" ? "Approved orders needing payment verification and proof-of-payment upload." : role === "store_keeper" ? "Receipts and stock conditions requiring warehouse action." : role === "procurement_officer" ? "Records requiring direct procurement action or supplier follow-up." : "Items with a measurable workflow or control consequence.";
  return <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="text-sm">{title}</CardTitle><CardDescription>{description}</CardDescription></CardHeader><CardContent className="px-4 pb-4">{snapshot?.workQueue.length ? <div className="divide-y">{snapshot.workQueue.slice(0, 8).map((item) => <div key={item.id} className="flex items-center gap-3 py-2.5"><Badge variant={item.priority === "critical" || item.priority === "high" ? "destructive" : "secondary"} className="w-16 justify-center text-[10px] capitalize">{item.priority}</Badge><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.reference} · {item.title}</p><p className="truncate text-xs text-muted-foreground">{[item.supplier, item.location, item.status, item.dueAt ? `due ${format(new Date(item.dueAt), "dd MMM")}` : ""].filter(Boolean).join(" · ")}</p></div>{item.amount !== undefined && item.amount !== null && <span className="hidden text-sm font-semibold md:block">{formatMoney(item.amount, currency)}</span>}<Button size="sm" variant="ghost" onClick={() => navigate(item.nextAction?.toLowerCase().includes("stock") ? "/inventory" : item.nextAction?.toLowerCase().includes("receive") ? "/procurement" : "/procurement")}>{item.nextAction ?? "Review"}<ArrowRight className="size-3" /></Button></div>)}</div> : <EmptyPanel icon={ClipboardCheck} title="Work queue is clear" description="Live approvals, orders, receipts and stock actions will appear here." />}</CardContent></Card>;
}

function Exceptions({ snapshot, navigate }: { snapshot?: OperationsDashboardSnapshot; navigate: (path: string) => void }) { return <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="flex items-center gap-2 text-sm"><AlertTriangle className="size-4 text-amber-500" />Exceptions</CardTitle><CardDescription>Delayed records requiring intervention.</CardDescription></CardHeader><CardContent className="px-4 pb-4">{snapshot?.exceptions.length ? <div className="space-y-2">{snapshot.exceptions.slice(0, 6).map((item) => <button type="button" key={item.id} onClick={() => navigate("/logistics")} className="w-full rounded-lg border border-amber-500/25 bg-amber-500/[0.04] p-3 text-left hover:bg-amber-500/[0.08]"><div className="flex items-center justify-between"><p className="text-sm font-medium">{item.reference}</p><Badge variant="destructive" className="text-[10px]">{item.priority}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{item.title}{item.supplier ? ` · ${item.supplier}` : ""}</p></button>)}</div> : <EmptyPanel icon={CheckCircle2} title="No exceptions" description="Delayed deliveries and other workflow exceptions will be escalated here." />}</CardContent></Card>; }

function ChartCard({ title, description, children }: { title: string; description: string; children: ReactNode }) { return <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="text-sm">{title}</CardTitle><CardDescription>{description}</CardDescription></CardHeader><CardContent className="px-4 pb-4">{children}</CardContent></Card>; }
function SupplierCard({ snapshot, currency }: { snapshot?: OperationsDashboardSnapshot; currency: string }) { return <ChartCard title="Supplier performance" description="Order volume, committed spend and overdue deliveries.">{snapshot?.supplierPerformance.length ? <div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="border-b text-muted-foreground"><tr><th className="pb-2 font-medium">Supplier</th><th className="pb-2 text-right font-medium">Orders</th><th className="pb-2 text-right font-medium">Spend</th><th className="pb-2 text-right font-medium">Late</th></tr></thead><tbody className="divide-y">{snapshot.supplierPerformance.map((supplier) => <tr key={supplier.name}><td className="py-2 font-medium">{supplier.name}</td><td className="py-2 text-right">{supplier.orders}</td><td className="py-2 text-right">{formatMoney(supplier.spend, currency)}</td><td className="py-2 text-right">{supplier.overdue ? <Badge variant="destructive" className="text-[10px]">{supplier.overdue}</Badge> : <span className="text-emerald-600">0</span>}</td></tr>)}</tbody></table></div> : <EmptyPanel icon={ShieldCheck} title="No supplier history yet" description="Supplier performance will appear once purchase orders exist." />}</ChartCard>; }
function WarehouseCard({ snapshot, currency, hasWarehouse }: { snapshot?: OperationsDashboardSnapshot; currency: string; hasWarehouse: boolean }) { return <ChartCard title="Warehouse comparison" description="Current units and inventory value by authorized warehouse.">{hasWarehouse ? <div className="space-y-2">{snapshot?.warehouseComparison.map((warehouse) => <div key={warehouse.id} className="flex items-center gap-3"><span className="w-28 truncate text-xs font-medium">{warehouse.name}</span><div className="h-2 flex-1 rounded-full bg-muted"><div className="h-2 rounded-full bg-primary" style={{ width: `${Math.min(100, Math.max(4, (warehouse.units / Math.max(...(snapshot?.warehouseComparison.map((item) => item.units) ?? [1]))) * 100))}%` }} /></div><span className="w-24 text-right text-[11px] text-muted-foreground">{warehouse.units.toLocaleString()} · {formatMoney(warehouse.value, currency)}</span></div>)}</div> : <EmptyPanel icon={Warehouse} title="No warehouse balances yet" description="Warehouse comparison will populate when stock is recorded." />}</ChartCard>; }

function ActivityPanel({ snapshot, role }: { snapshot?: OperationsDashboardSnapshot; role: DashboardRole }) { return <Card className="shadow-sm"><CardHeader className="px-4 py-3"><CardTitle className="flex items-center gap-2 text-sm"><Activity className="size-4" />{role === "super_admin" ? "System activity" : "Recent activity"}</CardTitle><CardDescription>{role === "super_admin" ? "Recent stock-ledger events across the organization." : "Recent actions relevant to this operational area."}</CardDescription></CardHeader><CardContent className="px-4 pb-4">{snapshot?.activity.length ? <div className="grid gap-3 md:grid-cols-2">{snapshot.activity.slice(0, 8).map((event) => <div key={event.id} className="flex gap-3"><div className="mt-1.5 size-2 shrink-0 rounded-full bg-primary" /><div className="min-w-0"><p className="truncate text-sm"><span className="font-medium">{event.actor}</span> {event.action} <span className="font-medium">{event.reference}</span></p><p className="text-xs text-muted-foreground">{formatDistanceToNow(new Date(event.occurredAt), { addSuffix: true })} · {stageMeta[event.stage]?.label ?? "Workflow"}</p></div></div>)}</div> : <EmptyPanel icon={Activity} title="No activity yet" description="Live ledger events will appear here as goods move through the system." />}</CardContent></Card>; }

function findMetric(snapshot: OperationsDashboardSnapshot | undefined, key: string) { return snapshot?.metrics.find((metric) => metric.key === key)?.value ?? 0; }
function EmptyPanel({ icon: Icon, title, description }: { icon: ElementType; title: string; description: string }) { return <div className="flex min-h-28 flex-col items-center justify-center px-4 py-4 text-center"><Icon className="mb-2 size-7 text-muted-foreground/40" /><p className="text-sm font-medium">{title}</p><p className="mt-1 max-w-sm text-xs text-muted-foreground">{description}</p></div>; }
